// === Tab: mySketch ===
ArrayList<Particle> particles;

function setup() {
  //createCanvas(windowWidth, windowHeight, WEBGL);
	createCanvas(600, 600);
  frameRate(100);
  //
  rectMode(CENTER);
  colorMode(HSB, 256);
  noStroke();
  particles = new ArrayList<Particle>();
  for (i=0; i<123; i++) {
    let delay = floor(random(500));
    particles.add(new Particle(new PVector(random(-100, 100), random(-100, 100)), delay));
  }
  background(255);
}

function draw() {
  //background(255);
  translate(width/2, height/2);
  for (let p of particles) {
    p.update();
    p.draw();
  }
  //saveFrame("frames/part_####.png");
}


class Particle {
  pos;
  vel;
  gravity;
  phase;
  amp;
  freq;
  target;
  delay;
  angle;
  angVel;
  w, h;
  col;
  col2;

  constructor(pos, delay) {
    this.pos = pos;
    this.vel = new PVector(0, 0);
    this.gravity = new PVector(0, random(0.01, 0.012));
    this.phase = random(TWO_PI);
    this.amp = random(0.01, 0.08);
    this.freq = random(-0.1, 0.1);
    this.target = new PVector(0, 500);
    this.delay = delay;
    this.angle = random(TWO_PI);
    this.angVel = random(-0.05, 0.05);
    this.w = random(8, 15);
    this.h = random(10, 20);
    this.col = color(random(255), 200, 200);
    this.col2 = color(random(255), 200, 100, 127); 
  }

  function update() {
    if (this.delay > 0) {
      this.delay--;
    } else {
      this.angVel += random(-0.002, 0.002);
      this.angVel = constrain(this.angVel, -0.06, 0.06);
      this.angle += this.angVel;
      this.freq += random(-0.01, 0.01);
      this.freq = constrain(this.freq, -0.2, 0.2);
      this.amp += random(-0.0001, 0.0001);
      this.amp = constrain(this.amp, -0.25, 0.25);
      this.phase += this.freq;
      let zigzag = PVector.fromAngle(this.phase);
			zigzag.mult(this.amp);
      this.vel.add(zigzag);
      this.vel.limit(1.0);
      this.pos.add(this.vel);
    }
  }

  function draw() {
    pushMatrix();
    translate(this.pos.x, this.pos.y);
    pushMatrix();
    rotate(this.angle);
    fill(this.col2);
    rect(0, 0, this.w, this.h);
    popMatrix();
    translate(-2, -2);
    rotate(this.angle);
    fill(this.col);
    rect(0, 0, this.w, this.h);
    popMatrix();
  }
}

